#include <bits/stdc++.h>
using namespace std;

int main(){
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if(!(cin >> n)) return 0;

    string s;
    s.reserve(n);
    for(int i = 0; i < n; i++){
        int d;
        cin >> d;
        s.push_back((char)('0' + d));
    }

    for(int L = 1; L <= n; ++L){
        if(s[0] == '0') break; // A >= 1 não pode começar com 0
        string cur = s.substr(0, L); // candidata a A
        long long p = 0;
        bool ok = true;

        while(p < n){
            size_t len = cur.size();
            if((size_t)p + len > (size_t)n){ ok = false; break; }
            if(s.compare((size_t)p, len, cur) != 0){ ok = false; break; }
            p += (long long)len;

            // incrementa cur (inteiro grande em string)
            int i = (int)len - 1;
            while(i >= 0 && cur[i] == '9'){ cur[i] = '0'; --i; }
            if(i < 0) cur.insert(cur.begin(), '1');
            else cur[i]++;
        }

        if(ok){
            cout << s.substr(0, L) << "\n";
            return 0;
        }
    }
    return 0;
}
```

**Explicação da abordagem:**

- Todos os dígitos de A devem ser exatamente os primeiros `L` dígitos da lousa (sem zero à esquerda, pois A ≥ 1). Testamos todos os comprimentos `L` de 1 a N, em ordem crescente — como números com menos dígitos são menores, o primeiro `L` que funcionar dá o menor A possível (para um mesmo `L`, A é único).
- Para um A candidato, simulamos a sequência A, A+1, A+2, ... comparando cada número (com incremento de inteiro grande feito na string) contra a lousa. A resposta é válida se todos os prefixos casarem e a lousa terminar exatamente num limite entre dois números.
- Custo total: para cada `L`, o custo das comparações é proporcional ao total de dígitos consumidos (≤ N) e os incrementos custam O(N) amortizados, dando O(N²) no total (≈ 10⁶ operações para N = 1000), o que é facilmente suficiente.

